import React from 'react';
import { motion } from 'framer-motion';
import { useSettings } from '../../context/SettingsContext';
import styles from './ProgressBar.module.css';

const ProgressBar = ({
  value = 0, // 0-100
  max = 100,
  variant = 'default', // 'default', 'gradient', 'striped'
  size = 'md', // 'sm', 'md', 'lg'
  showLabel = false,
  label,
  animated = true,
  className = '',
}) => {
  const { settings } = useSettings();
  const percentage = Math.min(100, Math.max(0, (value / max) * 100));
  
  const progressVariants = {
    initial: { width: 0 },
    animate: { 
      width: `${percentage}%`,
      transition: { 
        duration: 0.8, 
        ease: [0.34, 1.56, 0.64, 1] // Custom spring-like ease
      }
    }
  };

  const classNames = [
    styles.progressBar,
    styles[variant],
    styles[size],
    animated && styles.animated,
    className,
  ].filter(Boolean).join(' ');

  return (
    <div className={styles.wrapper}>
      {(showLabel || label) && (
        <div className={styles.labelRow}>
          <span className={styles.label}>{label}</span>
          {showLabel && <span className={styles.percentage}>{Math.round(percentage)}%</span>}
        </div>
      )}
      <div className={classNames}>
        <motion.div
          className={styles.fill}
          variants={settings.animationsEnabled ? progressVariants : {}}
          initial="initial"
          animate="animate"
          style={{ width: settings.animationsEnabled ? undefined : `${percentage}%` }}
        />
      </div>
    </div>
  );
};

export default ProgressBar;
